#define PI 3.14159265359
#define TAU 2*PI

float sdCircle(in vec2 p, in float hr) {
    return length(p) - hr;
}

float sdRectangle(in vec2 p, in vec2 hsize) {
    vec2 d = abs(p) - hsize;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

float sdScene(in vec2 p, float t) {
    p.x += cos(t * 0.2) * 0.072 + sin(p.y * 1.5);
    p.y += sin(t * 0.6) * 0.05 + cos(p.x * 2.0) + t * 0.3;

    float s = 0.5 + abs(sin(t * 0.04)) * 0.25;
    p = mod(p, s) - (s * sin(t * 0.18));
    float d1 = sdRectangle(abs(p) - vec2(0.025, 0.075), 0.05 + vec2(abs(cos(t * 0.4) * 0.055)));
    float d2 = sdCircle(p, 0.1 + sin(t * 0.2) * 0.158);

    float d = min(d1, max(d1, d2)) - 0.0025;

    return d;
}

vec3 pal(float t) {
    vec3 d = vec3(0.2, 0.2, 0.7);
    vec3 b = vec3(0.2, 0.0, 0.8);
    vec3 c = vec3(1.0, 0.2, 0.25);
    vec3 a = vec3(0.5, 0.0, 0.1);

    return a - b * (cos(t * c) + d);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    // Pixel coordinates (from -1 to 1)
    vec2 uv = 2.0 * fragCoord/iResolution.xy - 1.0;

    // Correct aspect ratio
    uv.x *= iResolution.x / iResolution.y;

    // Draw scene
    float t = iTime + 17.0;
    uv *= 0.2 + abs(sin(-10.0 + t * 0.01)) * 4.0;

    float d = sdScene(uv, t);

    // Pixel color
    vec3 col = vec3(0.1, 0.1, 0.4);

    col = d < 0.25 ? vec3(0.1, 0.2, 1.0) : col;
    col = mix(vec3(d * 0.3, 0.0, d * 1.9), col, 0.4);

    col = mix(col, pal(t + cos(uv.x) * 3.0 + sin(uv.y) * 4.0), 0.75);

    // Output to screen
    fragColor = vec4(col,1.0);
}
